///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_Chk_form
 * @description Chk form 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_Chk_form = async function () {
    const sbmOptions = {
        id: "tx_Chk_form",
        method: "post",
        action: "/fee/fee.do?method=grntFeeInfoView",
        ref: "dma_ChkFormReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fnRegSave
 * @description fn Reg Save 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnRegSave = async function () {
    const sbmOptions = {
        id: "tx_fnRegSave",
        method: "post",
        action: "/stdcd/cd.do?method=cdProcess",
        ref: "dma_fnRegSaveReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

